import{_ as e,o as l,c as a,a4 as d}from"./chunks/framework.BUqnS5H7.js";const o=JSON.parse('{"title":"MySQL 参数速查","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/reference/parameters.md","filePath":"mysql/reference/parameters.md"}'),r={name:"mysql/reference/parameters.md"};function s(i,t,n,f,c,y){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="mysql-参数速查" tabindex="-1" data-src-line="1" data-src-file="mysql/reference/parameters.md">MySQL 参数速查 <a class="header-anchor" href="#mysql-参数速查" aria-label="Permalink to &quot;MySQL 参数速查&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="mysql/reference/parameters.md"><p data-src-line="3" data-src-file="mysql/reference/parameters.md">生产环境最常调整的参数，按功能分类。所有参数均基于 MySQL 8.0。</p></blockquote><h2 id="连接与线程" tabindex="-1" data-src-line="5" data-src-file="mysql/reference/parameters.md">连接与线程 <a class="header-anchor" href="#连接与线程" aria-label="Permalink to &quot;连接与线程&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="mysql/reference/parameters.md"><tr data-src-line="7" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="9" data-src-file="mysql/reference/parameters.md"><tr data-src-line="9" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>max_connections</code></td><td style="text-align:left;">151</td><td style="text-align:left;">500~2000</td><td style="text-align:left;">最大连接数，按业务并发调整</td></tr><tr data-src-line="10" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>max_connect_errors</code></td><td style="text-align:left;">100</td><td style="text-align:left;">100000</td><td style="text-align:left;">连续错误次数上限，超过后拒绝连接</td></tr><tr data-src-line="11" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>wait_timeout</code></td><td style="text-align:left;">28800</td><td style="text-align:left;">300~600</td><td style="text-align:left;">空闲连接超时（秒）</td></tr><tr data-src-line="12" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>interactive_timeout</code></td><td style="text-align:left;">28800</td><td style="text-align:left;">300~600</td><td style="text-align:left;">交互式连接超时（秒）</td></tr><tr data-src-line="13" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>thread_cache_size</code></td><td style="text-align:left;">9</td><td style="text-align:left;">64~128</td><td style="text-align:left;">线程缓存，减少线程创建开销</td></tr></tbody></table><h2 id="innodb-缓冲池" tabindex="-1" data-src-line="15" data-src-file="mysql/reference/parameters.md">InnoDB 缓冲池 <a class="header-anchor" href="#innodb-缓冲池" aria-label="Permalink to &quot;InnoDB 缓冲池&quot;">​</a></h2><table tabindex="0"><thead data-src-line="17" data-src-file="mysql/reference/parameters.md"><tr data-src-line="17" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="19" data-src-file="mysql/reference/parameters.md"><tr data-src-line="19" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_buffer_pool_size</code></td><td style="text-align:left;">128M</td><td style="text-align:left;">物理内存的 60%~80%</td><td style="text-align:left;">最关键参数，决定缓存能力</td></tr><tr data-src-line="20" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_buffer_pool_instances</code></td><td style="text-align:left;">1</td><td style="text-align:left;">8（≥8G 内存时）</td><td style="text-align:left;">缓冲池实例数，减少锁竞争</td></tr><tr data-src-line="21" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_buffer_pool_dump_at_shutdown</code></td><td style="text-align:left;">ON</td><td style="text-align:left;">ON</td><td style="text-align:left;">关闭时保存热数据索引</td></tr><tr data-src-line="22" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_buffer_pool_load_at_startup</code></td><td style="text-align:left;">ON</td><td style="text-align:left;">ON</td><td style="text-align:left;">启动时加载热数据索引</td></tr></tbody></table><h2 id="redo-log" tabindex="-1" data-src-line="24" data-src-file="mysql/reference/parameters.md">Redo Log <a class="header-anchor" href="#redo-log" aria-label="Permalink to &quot;Redo Log&quot;">​</a></h2><table tabindex="0"><thead data-src-line="26" data-src-file="mysql/reference/parameters.md"><tr data-src-line="26" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="28" data-src-file="mysql/reference/parameters.md"><tr data-src-line="28" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_redo_log_capacity</code></td><td style="text-align:left;">100M</td><td style="text-align:left;">1G~4G</td><td style="text-align:left;">Redo Log 总大小（8.0.30+）</td></tr><tr data-src-line="29" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_flush_log_at_trx_commit</code></td><td style="text-align:left;">1</td><td style="text-align:left;">1（强一致）/ 2（高性能）</td><td style="text-align:left;">1=每次提交刷盘，2=每秒刷盘</td></tr><tr data-src-line="30" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_log_buffer_size</code></td><td style="text-align:left;">16M</td><td style="text-align:left;">64M~256M</td><td style="text-align:left;">日志缓冲区大小</td></tr></tbody></table><h2 id="binlog" tabindex="-1" data-src-line="32" data-src-file="mysql/reference/parameters.md">Binlog <a class="header-anchor" href="#binlog" aria-label="Permalink to &quot;Binlog&quot;">​</a></h2><table tabindex="0"><thead data-src-line="34" data-src-file="mysql/reference/parameters.md"><tr data-src-line="34" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="36" data-src-file="mysql/reference/parameters.md"><tr data-src-line="36" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>log_bin</code></td><td style="text-align:left;">OFF</td><td style="text-align:left;">ON</td><td style="text-align:left;">开启 Binlog（主从复制必须）</td></tr><tr data-src-line="37" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>binlog_format</code></td><td style="text-align:left;">ROW</td><td style="text-align:left;">ROW</td><td style="text-align:left;">推荐 ROW 格式</td></tr><tr data-src-line="38" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>binlog_expire_logs_seconds</code></td><td style="text-align:left;">2592000</td><td style="text-align:left;">604800</td><td style="text-align:left;">Binlog 保留时间（秒）</td></tr><tr data-src-line="39" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>sync_binlog</code></td><td style="text-align:left;">1</td><td style="text-align:left;">1（强一致）/ 100（高性能）</td><td style="text-align:left;">每 N 次提交同步 Binlog</td></tr></tbody></table><h2 id="查询与排序" tabindex="-1" data-src-line="41" data-src-file="mysql/reference/parameters.md">查询与排序 <a class="header-anchor" href="#查询与排序" aria-label="Permalink to &quot;查询与排序&quot;">​</a></h2><table tabindex="0"><thead data-src-line="43" data-src-file="mysql/reference/parameters.md"><tr data-src-line="43" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="45" data-src-file="mysql/reference/parameters.md"><tr data-src-line="45" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>sort_buffer_size</code></td><td style="text-align:left;">256K</td><td style="text-align:left;">2M~4M</td><td style="text-align:left;">每个会话的排序缓冲区</td></tr><tr data-src-line="46" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>join_buffer_size</code></td><td style="text-align:left;">256K</td><td style="text-align:left;">2M~4M</td><td style="text-align:left;">连接缓冲区</td></tr><tr data-src-line="47" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>tmp_table_size</code></td><td style="text-align:left;">16M</td><td style="text-align:left;">64M~128M</td><td style="text-align:left;">内存临时表大小上限</td></tr><tr data-src-line="48" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>max_heap_table_size</code></td><td style="text-align:left;">16M</td><td style="text-align:left;">64M~128M</td><td style="text-align:left;">内存引擎表大小上限</td></tr><tr data-src-line="49" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>long_query_time</code></td><td style="text-align:left;">10</td><td style="text-align:left;">1</td><td style="text-align:left;">慢查询阈值（秒）</td></tr><tr data-src-line="50" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>slow_query_log</code></td><td style="text-align:left;">OFF</td><td style="text-align:left;">ON</td><td style="text-align:left;">开启慢查询日志</td></tr></tbody></table><h2 id="字符集与排序规则" tabindex="-1" data-src-line="52" data-src-file="mysql/reference/parameters.md">字符集与排序规则 <a class="header-anchor" href="#字符集与排序规则" aria-label="Permalink to &quot;字符集与排序规则&quot;">​</a></h2><table tabindex="0"><thead data-src-line="54" data-src-file="mysql/reference/parameters.md"><tr data-src-line="54" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="56" data-src-file="mysql/reference/parameters.md"><tr data-src-line="56" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>character_set_server</code></td><td style="text-align:left;">utf8mb4</td><td style="text-align:left;">utf8mb4</td><td style="text-align:left;">服务端字符集</td></tr><tr data-src-line="57" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>collation_server</code></td><td style="text-align:left;">utf8mb4_0900_ai_ci</td><td style="text-align:left;">utf8mb4_0900_ai_ci</td><td style="text-align:left;">服务端排序规则</td></tr></tbody></table><h2 id="安全" tabindex="-1" data-src-line="59" data-src-file="mysql/reference/parameters.md">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h2><table tabindex="0"><thead data-src-line="61" data-src-file="mysql/reference/parameters.md"><tr data-src-line="61" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="63" data-src-file="mysql/reference/parameters.md"><tr data-src-line="63" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>local_infile</code></td><td style="text-align:left;">ON</td><td style="text-align:left;">OFF</td><td style="text-align:left;">禁止 LOAD DATA LOCAL</td></tr><tr data-src-line="64" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>skip_symbolic_links</code></td><td style="text-align:left;">OFF</td><td style="text-align:left;">ON</td><td style="text-align:left;">禁用符号链接</td></tr><tr data-src-line="65" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>sql_mode</code></td><td style="text-align:left;">（含多种）</td><td style="text-align:left;">STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION</td><td style="text-align:left;">严格模式</td></tr></tbody></table>',16)])])}const g=e(r,[["render",s]]);export{o as __pageData,g as default};
